#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
com_scan_headless.py (SAFE)
- Avoids hangs by adding per-device timeout around Get-PnpDeviceProperty
- Still returns ["112","106","114","107"] style ports
Output JSON to stdout:
  {"ok": true, "ports": ["112","106","114","107"], "depth": 3}
"""

import json
import re
import subprocess
import time
from typing import Dict, List, Tuple, Optional

GENERIC_NAMES = {
    "USB INPUT DEVICE",
    "USB COMPOSITE DEVICE",
    "GENERIC USB HUB",
    "USB ROOT HUB (USB 3.0)",
    "USB ROOT HUB",
    "UNKNOWN",
    "",
    None,
}

def extract_vidpid(instance_id: str) -> str:
    m_vid = re.search(r"VID_([0-9A-Fa-f]{4})", instance_id or "")
    m_pid = re.search(r"PID_([0-9A-Fa-f]{4})", instance_id or "")
    if not (m_vid and m_pid):
        return "-"
    return str(m_vid.group(1)).upper() + ":" + str(m_pid.group(1)).upper()

def hub_socket_key(location_path: str, depth_after_root: int) -> Optional[str]:
    if not location_path or "#USBROOT" not in location_path:
        return None
    tail = location_path.split("#USBROOT", 1)[1]
    tail = re.sub(r"^\(\d+\)#", "", tail)
    parts = [p for p in tail.split("#") if p.upper().startswith("USB(")]
    if len(parts) < depth_after_root:
        return None
    return "#".join(parts[:depth_after_root])

def com_from_best_device_name(name: str) -> str:
    if not name:
        return "-"
    m = re.search(r"-(\s*)(\d{3,4})\s*$", str(name).strip())
    if not m:
        return "-"
    num = m.group(2)
    try:
        return str(int(num))
    except Exception:
        return "-"

def powershell_scan_usb_safe() -> Tuple[Optional[List[dict]], Optional[str]]:
    # Per-device timeout wrapper avoids the hang you are seeing.
    ps = r"""
$ErrorActionPreference = "SilentlyContinue"
$ProgressPreference = "SilentlyContinue"

$devices = Get-PnpDevice -PresentOnly |
  Where-Object {
    $_.InstanceId -like "USB*" -and
    $_.FriendlyName -match "-\s*\d{3,4}\s*$"
  } |
  Select-Object -First 40

$rows = @()

foreach ($d in $devices) {
  $id = $d.InstanceId
  $name = $d.FriendlyName
  $lp = $null

  try {
    $job = Start-Job -ScriptBlock {
      param($iid)
      $x = (Get-PnpDeviceProperty -InstanceId $iid -KeyName "DEVPKEY_Device_LocationPaths" -ErrorAction SilentlyContinue).Data |
            Select-Object -First 1
      $x
    } -ArgumentList $id

    $null = Wait-Job $job -Timeout 2

    if ($job.State -eq "Running") {
      Stop-Job $job | Out-Null
      Remove-Job $job | Out-Null
      $lp = $null
    } else {
      $lp = Receive-Job $job
      Remove-Job $job | Out-Null
    }
  } catch {
    $lp = $null
  }

  $rows += [PSCustomObject]@{ Name=$name; InstanceId=$id; LocationPath=$lp }
}

$rows | ConvertTo-Json -Depth 6 -Compress
"""
    try:
        out = subprocess.check_output(
            ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps],
            text=True,
            stderr=subprocess.STDOUT,
        ).strip()

        if not out:
            return [], None

        data = json.loads(out)
        if isinstance(data, dict):
            data = [data]
        return data, None

    except subprocess.CalledProcessError as e:
        return None, "PowerShell error: " + str(e.output)
    except Exception as e:
        return None, "Python error: " + str(e)

def group_by_hubkey(rows: List[dict], depth: int) -> Dict[str, dict]:
    grouped: Dict[str, dict] = {}
    for r in rows:
        name = (r.get("Name") or "").strip()
        inst = (r.get("InstanceId") or "").strip()
        lp = (r.get("LocationPath") or "").strip()

        key = hub_socket_key(lp, depth_after_root=depth)
        if not key:
            continue

        vidpid = extract_vidpid(inst)

        row = grouped.setdefault(key, {"best_name": None, "vidpid": "-", "count": 0, "com": "-"})
        row["count"] += 1

        if row["best_name"] is None:
            row["best_name"] = name
        else:
            cur = (row["best_name"] or "").upper()
            cand = (name or "").upper()
            if cur in GENERIC_NAMES and cand not in GENERIC_NAMES and cand:
                row["best_name"] = name

        if row["vidpid"] == "-" and vidpid != "-":
            row["vidpid"] = vidpid

        row["com"] = com_from_best_device_name(row.get("best_name") or "")

    for _, v in grouped.items():
        v["com"] = com_from_best_device_name(v.get("best_name") or "")

    return grouped

def pick_best_grouping(rows: List[dict]) -> Tuple[Dict[str, dict], int]:
    best = {}
    best_depth = 3
    best_keys = -1
    for d in (3, 2, 4):
        g = group_by_hubkey(rows, depth=d)
        k = len(g)
        if k > best_keys:
            best = g
            best_keys = k
            best_depth = d
    return best, best_depth

def fallback_ports_from_names(rows: List[dict]) -> List[str]:
    ports = []
    for r in (rows or []):
        c = com_from_best_device_name((r.get("Name") or "").strip())
        if c != "-" and c not in ports:
            ports.append(c)
    # stable numeric sort
    try:
        ports = sorted(ports, key=lambda x: int(x))
    except Exception:
        pass
    return ports[:4]

def main() -> int:
    retries = 2
    delay = 0.25
    last_err = None

    for _ in range(retries):
        rows, err = powershell_scan_usb_safe()
        if err:
            last_err = err
            time.sleep(delay)
            continue

        rows = rows or []
        grouped, depth = pick_best_grouping(rows)

        if grouped:
            items = sorted(grouped.items(), key=lambda kv: kv[0])
            ports: List[str] = []
            for _, info in items:
                com = (info.get("com") or "-").strip()
                if com != "-" and com not in ports:
                    ports.append(com)
                if len(ports) >= 4:
                    break
            if ports:
                print(json.dumps({"ok": True, "ports": ports, "depth": depth}))
                return 0

        # fallback if location paths are missing / timed out
        ports2 = fallback_ports_from_names(rows)
        if ports2:
            print(json.dumps({"ok": True, "ports": ports2, "depth": 0}))
            return 0

        time.sleep(delay)

    print(json.dumps({"ok": False, "error": last_err or "No ports found", "ports": []}))
    return 2

if __name__ == "__main__":
    raise SystemExit(main())

