# ============================================================
# Server Script (API) : pts1_api
# RestrictedPython-safe:
# - NO imports
# - NO .format()
# - NO f-strings
#
# IMPORTANT:
# Frappe uses form_dict["cmd"] = "pts1_api" internally.
# So we use "api_cmd" for our routing.
# ============================================================

form = frappe.form_dict or {}

# --------- extract payload safely ----------
payload = {}

wrapped = form.get("args")

# prefer wrapped args (this is where frappe.call puts your args)
if isinstance(wrapped, dict):
    for k in wrapped:
        payload[k] = wrapped[k]
elif isinstance(wrapped, str):
    try:
        j = frappe.parse_json(wrapped)
        if isinstance(j, dict):
            for k in j:
                payload[k] = j[k]
    except Exception:
        pass

# also accept direct keys (but DO NOT copy framework "cmd")
for k in form:
    if k != "args" and k != "cmd":
        payload[k] = form[k]

# our command
api_cmd = (payload.get("api_cmd") or "").strip().lower()

# backward compatibility if someone sends cmd INSIDE wrapped args
if not api_cmd:
    c2 = payload.get("cmd")
    if c2 and str(c2).strip().lower() != "pts1_api":
        api_cmd = str(c2).strip().lower()

docname = (payload.get("docname") or "").strip()

# fallback
if (not api_cmd) and docname:
    api_cmd = "request_find_com"

# --------- helpers ----------
def to_dict(x):
    if not x:
        return {}
    if isinstance(x, dict):
        return x
    try:
        v = frappe.parse_json(x)
        if isinstance(v, dict):
            return v
    except Exception:
        pass
    return {}

def to_list(x):
    if not x:
        return []
    if isinstance(x, list):
        return x
    try:
        v = frappe.parse_json(x)
        if isinstance(v, list):
            return v
    except Exception:
        pass
    return []

def get_pts_doc(name):
    return frappe.get_doc("PTS1 Test", name)

def get_lane_row(doc, lane_no):
    ln = int(lane_no or 0)
    for r in (doc.lanes or []):
        if int(r.lane_no or 0) == ln:
            return r
    frappe.throw("Lane not found")

def safe_upper(x):
    try:
        return (x or "").strip().upper()
    except Exception:
        return ""

def ledger_is_in_pts_testing(ledger):
    """
    Accept PTS testing if ANY of these indicate PTS testing:
      1) lifecycle_stage == PTS_TESTING
      2) current_status/status == UNDER_PTS_TESTING
      3) timeline has event_type UNDER_PTS_TESTING or PTS_TESTING or MOVED_TO_PTS_TESTING
    """
    # 1) lifecycle stage
    st1 = safe_upper(ledger.get("lifecycle_stage"))
    if st1 == "PTS_TESTING":
        return True

    # 2) status/current status
    st2 = safe_upper(ledger.get("current_status"))
    st3 = safe_upper(ledger.get("status"))
    if st2 == "UNDER_PTS_TESTING" or st3 == "UNDER_PTS_TESTING":
        return True

    # 3) timeline
    tl = ledger.get("pcb_ledger_timeline") or []
    for r in tl:
        ev = safe_upper(r.get("event_type"))
        if ev == "UNDER_PTS_TESTING" or ev == "PTS_TESTING" or ev == "MOVED_TO_PTS_TESTING":
            return True

    return False

out = {"ok": False, "api_cmd": api_cmd}

# ============================================================
# request_lane_action
# ============================================================
if api_cmd == "request_lane_action":
    docname = (payload.get("docname") or "").strip()
    lane_no = int(payload.get("lane_no") or 0)
    action = (payload.get("action") or "").strip().upper()

    if not docname:
        frappe.throw("Missing docname")
    if lane_no not in (1, 2, 3, 4):
        frappe.throw("lane_no must be 1..4")
    if action != "VERIFY" and action != "FLASH":
        frappe.throw("action must be VERIFY or FLASH")

    doc = get_pts_doc(docname)
    row = get_lane_row(doc, lane_no)

    if (row.pcb_serial_no or "").strip() == "" or (row.com_port or "").strip() == "":
        frappe.throw("Lane " + str(lane_no) + ": PCB Serial No and COM Port are required")

    row.lane_action = action
    row.lane_action_status = "Requested"
    row.lane_status = "Queued"
    row.lane_progress = 0
    row.lane_action_message = ""
    row.error_message = ""

    try:
        doc.test_status = "Queued"
    except Exception:
        pass

    doc.save(ignore_permissions=True)
    frappe.db.commit()

    out = {"ok": True, "api_cmd": api_cmd, "doc": docname, "lane": lane_no, "action": action}

# ============================================================
# reset_lane
# ============================================================
elif api_cmd == "reset_lane":
    pts1_docname = (payload.get("pts1_docname") or payload.get("docname") or payload.get("name") or "").strip()
    lane_no = int(payload.get("lane_no") or 0)

    if not pts1_docname or not lane_no:
        frappe.throw("Missing pts1_docname / lane_no")

    doc = get_pts_doc(pts1_docname)
    row = get_lane_row(doc, lane_no)

    row.error_message = ""
    row.lane_log = ""
    row.lane_result_json = ""
    row.lane_progress = 0
    row.lane_step = ""
    row.lane_status = "Pending"
    row.lane_action_message = ""
    row.lane_action_status = ""
    row.lane_action = ""

    try:
        row.mac_id = ""
    except Exception:
        pass
    try:
        row.fw_file = ""
    except Exception:
        pass

    doc.save(ignore_permissions=True)
    frappe.db.commit()

    out = {"ok": True, "api_cmd": api_cmd}

# ============================================================
# request_find_com
# ============================================================
elif api_cmd == "request_find_com":
    docname = (payload.get("docname") or "").strip()
    if not docname:
        frappe.throw("Missing docname")

    doc = get_pts_doc(docname)

    # these fields must exist on doctype; if not, this will throw
    # (you already added them earlier, so ok)
    doc.find_com_status = "Requested"
    doc.find_com_message = ""
    doc.save(ignore_permissions=True)
    frappe.db.commit()

    out = {"ok": True, "api_cmd": api_cmd, "status": "Requested", "docname": docname}

# ============================================================
# update_find_com_result
# ============================================================
elif api_cmd == "update_find_com_result":
    docname = (payload.get("docname") or "").strip()
    status = (payload.get("status") or "").strip()
    message = (payload.get("message") or "").strip()
    ports = payload.get("ports")

    if not docname:
        frappe.throw("Missing docname")
    if status != "Running" and status != "Done" and status != "Failed":
        frappe.throw("status must be Running/Done/Failed")

    doc = get_pts_doc(docname)
    doc.find_com_status = status
    doc.find_com_message = message

    if status == "Done" and ports:
        ports_list = to_list(ports)
        lanes = sorted((doc.lanes or []), key=lambda r: int(r.lane_no or 0))
        i = 0
        for row in lanes:
            if i < len(ports_list):
                row.com_port = str(ports_list[i])
            i += 1

    doc.save(ignore_permissions=True)
    frappe.db.commit()

    out = {"ok": True, "api_cmd": api_cmd, "status": status, "docname": docname}

# ============================================================
# update_lane_fields
# ============================================================
elif api_cmd == "update_lane_fields":
    docname = (payload.get("docname") or "").strip()
    lane_no = int(payload.get("lane_no") or 0)
    fields = payload.get("fields")

    if not docname or not lane_no:
        frappe.throw("Missing docname / lane_no")

    fields = to_dict(fields)

    doc = get_pts_doc(docname)
    row = get_lane_row(doc, lane_no)

    allowed = {
        "lane_action", "lane_action_status", "lane_action_message",
        "lane_status", "lane_step", "lane_progress",
        "lane_log", "error_message", "mac_id",
        "lane_result_json", "pcb_serial_no", "com_port"
    }

    for k in fields:
        if k in allowed:
            try:
                row.set(k, fields[k])
            except Exception:
                pass

    doc.save(ignore_permissions=True)
    frappe.db.commit()

    out = {"ok": True, "api_cmd": api_cmd}

# ============================================================
# record_lane_run  (called by connector after each dump/flash)
# ============================================================
elif api_cmd == "record_lane_run":
    pts1_docname = (payload.get("pts1_docname") or payload.get("docname") or payload.get("name") or "").strip()
    lane_no = int(payload.get("lane_no") or 0)
    serial = (payload.get("serial") or "").strip()

    # op = dump / flash
    op = (payload.get("op") or "").strip().lower()

    # exit code: 0 = pass, else fail
    try:
        rc = int(payload.get("rc") or 0)
    except Exception:
        rc = 1

    # optional message and mac
    msg = (payload.get("message") or "").strip()
    mac = (payload.get("mac_id") or "").strip().upper()

    if not pts1_docname:
        frappe.throw("Missing pts1_docname/docname")
    if lane_no not in (1, 2, 3, 4):
        frappe.throw("lane_no must be 1..4")
    if not serial:
        frappe.throw("Missing serial")
    if op != "dump" and op != "flash":
        frappe.throw("op must be dump or flash")

    # time (IST)
    now_dt = frappe.db.sql("SELECT CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+05:30')", as_list=1)[0][0]


    # UPSERT: one record per serial (robust)
    res = None
    is_new_res = False

    exists = False
    try:
        exists = bool(frappe.db.exists("PTS1 Lane Result", serial))
    except Exception:
        exists = False

    if exists:
        res = frappe.get_doc("PTS1 Lane Result", serial)
    else:
        res = frappe.new_doc("PTS1 Lane Result")
        is_new_res = True

    # Keep identity fresh (must be set before insert)
    res.pcb_serial_no = serial
    res.lane_no = lane_no

    if mac:
        res.mac_id = mac
    # set status
    run_status = "Pass" if rc == 0 else "Fail"



    # ----- update dump/flash counters -----
    if op == "dump":
        try:
            res.dump_count = int(res.dump_count or 0) + 1
        except Exception:
            res.dump_count = 1

        res.dump_status = run_status
        res.dump_last_at = now_dt
        try:
            if not res.dump_first_at:
                res.dump_first_at = now_dt
        except Exception:
            pass

    if op == "flash":
        try:
            res.flash_count = int(res.flash_count or 0) + 1
        except Exception:
            res.flash_count = 1

        res.flash_status = run_status
        res.flash_last_at = now_dt
        try:
            if not res.flash_first_at:
                res.flash_first_at = now_dt
        except Exception:
            pass

    # store short run history in lane_result_json (append line)
    prev_hist = ""
    try:
        prev_hist = (res.lane_result_json or "")
    except Exception:
        prev_hist = ""

    line = (
        "ts=" + str(now_dt)
        + "|pts1_test=" + pts1_docname
        + "|lane=" + str(lane_no)
        + "|op=" + op
        + "|rc=" + str(rc)
        + "|status=" + run_status
    )
    if msg:
        line = line + "|msg=" + msg
    if mac:
        line = line + "|mac=" + mac

    new_hist = (prev_hist + "\n" + line).strip()
    if len(new_hist) > 12000:
        new_hist = new_hist[-12000:]
    res.lane_result_json = new_hist

    # save
    if is_new_res:
        res.insert(ignore_permissions=True)
    else:
        res.save(ignore_permissions=True)

    frappe.db.commit()
    out = {
        "ok": True,
        "api_cmd": api_cmd,
        "serial": serial,
        "op": op,
        "status": run_status,
        "at": str(now_dt),
        "mac_id": mac
    }

# ============================================================
# upload_result_to_master_ledger
# ============================================================
elif api_cmd == "upload_result_to_master_ledger":
    pts1_docname = (payload.get("pts1_docname") or payload.get("docname") or payload.get("name") or "").strip()
    lane_no = int(payload.get("lane_no") or 0)

    if not pts1_docname or not lane_no:
        frappe.throw("Missing pts1_docname / lane_no")

    pts = get_pts_doc(pts1_docname)
    lane = get_lane_row(pts, lane_no)

    serial = (lane.pcb_serial_no or "").strip()

    mac = (lane.mac_id or "").strip().upper()


    if not mac:
        try:
            mac = (frappe.db.get_value("PTS1 Lane Result", serial, "mac_id") or "").strip().upper()
        except Exception:
            mac = ""


    if not serial:
        frappe.throw("PCB Serial No missing")

    # Must be Done
    if (lane.lane_action_status or "").strip() != "Done":
        frappe.throw("Lane is not Done yet")

    # Prevent double-upload for same run (string marker)
    # NOTE: We detect it, but we DO NOT throw. Upload is idempotent (re-sync allowed).
    current_run_id = (pts.name or "") + "|" + str(lane_no) + "|" + (lane.lane_action_message or "") + "|" + (lane.lane_status or "")
    uploaded_already = False
    try:
        s = (lane.lane_result_json or "")
        if s:
            if ("uploaded=1" in s) and ("uploaded_run_id=" + current_run_id in s):
                uploaded_already = True
    except Exception:
        uploaded_already = False

    # DO NOT throw. Allow upload to re-apply updates (idempotent).
    # if uploaded_already:
    #     pass

    # Decide pass/fail based on lane_status
    pts1_status = "Pass"
    if (lane.lane_status or "").strip() != "Completed":
        pts1_status = "Fail"

    # Find PCB Ledger (try both: pcb_serial_no field and docname)
    ledger_name = frappe.db.get_value("PCB Ledger", {"pcb_serial_no": serial}, "name")
    if not ledger_name:
        # fallback: maybe pcb_serial_no is the docname
        ledger_name = frappe.db.get_value("PCB Ledger", serial, "name")

    if not ledger_name:
        rows = frappe.get_all("PCB Ledger", filters={"pcb_serial_no": serial}, fields=["name"], limit=1)
        ledger_name = rows[0]["name"] if rows else None

    if not ledger_name:
        frappe.throw("PCB Ledger not found for " + serial + ". PCB must exist in PCB Ledger before upload.")

    ledger = frappe.get_doc("PCB Ledger", ledger_name)

    # ✅ Updated guardrail: accept PTS_TESTING / UNDER_PTS_TESTING / timeline events
    if not ledger_is_in_pts_testing(ledger):
        frappe.throw("PCB " + serial + " is not in PTS Testing stage. Set Lifecycle Stage to PTS_TESTING or Status to UNDER_PTS_TESTING.")

    # Time (IST)
    now_dt = frappe.db.sql("SELECT CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+05:30')", as_list=1)[0][0]

    # Find PCB Master
    pcb_name = frappe.db.get_value("PCB Master", {"pcb_serial_no": serial}, "name")
    if not pcb_name:
        # fallback: maybe pcb_serial_no is docname
        pcb_name = frappe.db.get_value("PCB Master", serial, "name")

    if not pcb_name:
        frappe.throw("PCB Master not found for serial: " + serial)

    # Update PCB Master
    frappe.db.set_value("PCB Master", pcb_name, "pts1_status", pts1_status)
    frappe.db.set_value("PCB Master", pcb_name, "pts1_date", now_dt)
    frappe.db.set_value("PCB Master", pcb_name, "last_event_ref_doctype", "PTS1 Test")
    frappe.db.set_value("PCB Master", pcb_name, "last_event_ref_docname", pts.name)
    if mac:
        try:
            frappe.db.set_value("PCB Master", pcb_name, "mac_id", mac)
        except Exception:
            pass

    # Compute overall status from PCB Master values
    m = frappe.get_doc("PCB Master", pcb_name)
    p1u = safe_upper(m.get("pts1_status"))
    p2u = safe_upper(m.get("pts2_status"))
    p3u = safe_upper(m.get("pts3_status"))

    if p1u == "PASS" and p2u == "PASS" and p3u == "PASS":
        new_overall = "PASS"
    elif p1u == "FAIL" or p2u == "FAIL" or p3u == "FAIL":
        new_overall = "FAIL"
    elif p1u or p2u or p3u:
        new_overall = "PTS_PENDING"
    else:
        new_overall = (m.get("overall_status") or "PTS_PENDING")

    frappe.db.set_value("PCB Master", pcb_name, "overall_status", new_overall)

    # Update PCB Ledger
    frappe.db.set_value("PCB Ledger", ledger_name, "pts1_status", pts1_status)
    frappe.db.set_value("PCB Ledger", ledger_name, "pts1_date", now_dt)
    frappe.db.set_value("PCB Ledger", ledger_name, "overall_status", new_overall)
    frappe.db.set_value("PCB Ledger", ledger_name, "last_tested_on", now_dt)
    frappe.db.set_value("PCB Ledger", ledger_name, "last_event_ref_doctype", "PTS1 Test")
    frappe.db.set_value("PCB Ledger", ledger_name, "last_event_ref_docname", pts.name)
    if mac:
        try:
            frappe.db.set_value("PCB Ledger", ledger_name, "mac_id", mac)
        except Exception:
            pass


    # -----------------------------
    # UPSERT: PTS1 Lane Result
    # NOTE:
    # - Prefer DocType Auto Name = field: pcb_serial_no
    # - So we DO NOT force res.name in code.
    # -----------------------------
    # UPSERT: PTS1 Lane Result (robust)
    res = None
    is_new_res = False

    exists = False
    try:
        exists = bool(frappe.db.exists("PTS1 Lane Result", serial))
    except Exception:
        exists = False

    if exists:
        res = frappe.get_doc("PTS1 Lane Result", serial)
    else:
        res = frappe.new_doc("PTS1 Lane Result")
        is_new_res = True

    res.lane_no = lane_no
    res.pcb_serial_no = serial
    res.com_port = (lane.com_port or "")

    if mac:
        res.mac_id = mac
    elif (lane.mac_id or "").strip():
        res.mac_id = (lane.mac_id or "").strip().upper()


    try:
        res.fw_file = lane.fw_file
    except Exception:
        pass

    res.lane_action = (lane.lane_action or "")
    res.lane_action_status = (lane.lane_action_status or "")
    res.lane_action_message = (lane.lane_action_message or "")
    res.lane_status = (lane.lane_status or "")
    res.lane_step = (lane.lane_step or "")

    try:
        res.lane_progress = int(lane.lane_progress or 0)
    except Exception:
        res.lane_progress = 0

    res.lane_log = (lane.lane_log or "")
    res.error_message = (lane.error_message or "")
    # Append history text
    prev_hist = ""
    try:
        prev_hist = (res.lane_result_json or "")
    except Exception:
        prev_hist = ""

    entry = (
        "ts=" + str(now_dt)
        + "|pts1_test=" + (pts.name or "")
        + "|lane=" + str(lane_no)
        + "|action=" + (lane.lane_action or "")
        + "|status=" + (lane.lane_status or "")
        + "|msg=" + (lane.lane_action_message or "")
    )

    new_hist = (prev_hist + "\n" + entry).strip()
    if len(new_hist) > 8000:
        new_hist = new_hist[-8000:]

    res.lane_result_json = new_hist

    # Save (insert if new, else save)
    if is_new_res:
        res.insert(ignore_permissions=True)
    else:
        res.save(ignore_permissions=True)

    # Mark lane uploaded
    lane.lane_result_json = (
        "uploaded=1"
        + ";uploaded_at=" + str(now_dt)
        + ";pts1_result_id=" + (res.name or "")
        + ";uploaded_run_id=" + current_run_id
    )
    pts.save(ignore_permissions=True)

    frappe.db.commit()

    out = {
        "ok": True,
        "api_cmd": api_cmd,
        "serial": serial,
        "pts1_status": pts1_status,
        "pcb_master": pcb_name,
        "pcb_ledger": ledger_name,
        "pts1_result": res.name
    }

else:
    keys = ",".join(sorted([str(k) for k in payload.keys()]))
    frappe.throw("Invalid api_cmd: " + str(api_cmd) + " | payload keys=" + keys)

frappe.response["message"] = out
